40	    DuplicateChoiceIndex,
41	    /// The choices are rendered in reverse order, so choice 1 appears first (P-10).
42	    ReverseChoices,
43	    /// One function or legacy call of choice 0 loses the last character of its arguments, so they
44	    /// are not one complete JSON value (`incomplete_arguments`).
45	    TruncatedArgs,
46	    /// One function or legacy call of choice 0 gets two JSON objects as arguments (`{..}{"b":2}`).
47	    ConcatenatedObjects,
48	    /// Every call's arguments gain PascalCase, `constructor` and `prototype` keys. They are
49	    /// application data, so the stream is conforming (I-1).
50	    CapitalisedArgKeys,
51	    /// A chunk without a `choices` key (`chunk_without_choices` inside an open call).
52	    NoChoicesKey,
53	    /// A chunk whose choice 0 entry has no `delta` (`choice_without_delta` inside an open call).
54	    /// At an odd position, a delta-less `{"index":1}` is added behind the first record that opens
55	    /// a call instead (spec § 5.2, the opening record counts).
56	    NoDelta,
57	    /// A fragment with `"type":null` and a function body for call 0: a present `type` key counts
58	    /// as the type fragment, so it is a repeated type or a type/shape mismatch. When choice 0 has
59	    /// no call, a bare `{"index":0,"type":null}` goes after its first record instead: a conforming
60	    /// bodyless call that the core and the oracle both name `unknown`.
61	    NullType,
62	    /// A top-level `chunk` key with an empty `choices` (spec § 2.2 H1): LangChain reads
63	    /// `chunk.choices` then, so the hidden call sits inside `chunk`.
64	    ChunkKey,
65	    /// A fragment in a record with top-level `"type":"content.delta"` (spec § 2.2 H2): LangChain
66	    /// skips that record.
67	    ContentDeltaType,
68	    /// Two records with an array outside `tool_calls`, an indexed list and then a scalar list:
69	    /// openai-python's `accumulate_delta` raises at the second (spec § 5.7). The array sits under
70	    /// an unknown delta key, a tool-call entry key or a `function` key, chosen by the position.
71	    ArrayOutsideToolCalls,
72	    /// Two legacy `function_call` fragments with an extra key whose JSON type changes (`"x":"s"`,
