106	const ALLOWED: [&str; 2] = ["read_file", "send_mail"];
107	const BLOCKED: [&str; 2] = ["blocked_rm", "blocked_exfil"];
108	
109	fn call_strategy() -> impl Strategy<Value = Call> {
110	    (prop::bool::ANY, 0usize..2, "[a-z]{0,12}", 1usize..4, 0u8..10).prop_map(|(blocked, n, s, pieces, k)| {
111	        let name = if blocked { BLOCKED[n] } else { ALLOWED[n] };
112	        let args = if blocked { format!("{{\"v\":\"CANARY-{s}\"}}") } else { format!("{{\"v\":\"{s}\"}}") };
113	        let kind = match k {
114	            0 => CallKind::Custom,
115	            1 | 2 => CallKind::Legacy,
116	            _ => CallKind::Function,
117	        };
118	        Call { name, args, kind, pieces }
119	    })
120	}
121	
122	fn choice_strategy() -> impl Strategy<Value = Choice> {
123	    (prop::option::of("[a-zA-Z ]{1,10}"), prop::collection::vec(call_strategy(), 0..4), prop::option::of("[a-z ]{1,8}")).prop_map(|(before, mut calls, after)| {
124	        if calls.len() > 1 {
125	            for c in &mut calls {
126	                if c.kind == CallKind::Legacy {
127	                    c.kind = CallKind::Function; // a legacy call is the only call of its choice
128	                }
129	            }
130	        }
131	        Choice { before, calls, after }
132	    })
133	}
