135	fn quirk_strategy() -> impl Strategy<Value = Quirk> {
136	    prop_oneof![
137	        Just(Quirk::DuplicateDelta),
138	        Just(Quirk::CaseFoldedKey),
139	        Just(Quirk::ProtoKey),
140	        Just(Quirk::FloatIndex),
141	        Just(Quirk::BoolIndex),
142	        Just(Quirk::NegativeIndex),
143	        Just(Quirk::RepeatedName),
144	        Just(Quirk::Bom),
145	        Just(Quirk::LaxLine),
146	        Just(Quirk::UnknownFields),
147	        Just(Quirk::AfterDone),
148	        Just(Quirk::NoFinalBlank),
149	        Just(Quirk::Oversized),
150	        Just(Quirk::NaNRecord),
151	        Just(Quirk::JsonBody),
152	        Just(Quirk::EventLine),
153	        Just(Quirk::IndexGap),
154	        Just(Quirk::Comments),
155	        Just(Quirk::Interleave),
156	        Just(Quirk::EscapedKey),
157	        Just(Quirk::DropObject),
158	        Just(Quirk::MultiChoiceChunk),
159	        Just(Quirk::UnknownType),
160	        Just(Quirk::DuplicateChoiceIndex),
161	        Just(Quirk::ReverseChoices),
162	        Just(Quirk::TruncatedArgs),
163	        Just(Quirk::ConcatenatedObjects),
164	        Just(Quirk::CapitalisedArgKeys),
165	        Just(Quirk::NoChoicesKey),
166	        Just(Quirk::NoDelta),
167	        Just(Quirk::NullType),
168	        Just(Quirk::ChunkKey),
169	        Just(Quirk::ContentDeltaType),
170	        Just(Quirk::ArrayOutsideToolCalls),
171	        Just(Quirk::FunctionCallKey),
172	    ]
173	}
