192	fn split(s: &str, pieces: usize) -> Vec<String> {
193	    let chars: Vec<char> = s.chars().collect();
194	    let step = chars.len().div_ceil(pieces.max(1)).max(1);
195	    chars.chunks(step).map(|c| c.iter().collect()).collect()
196	}
