202	/// Arguments with keys that the envelope rules would reject (`Id`, `Name`, `constructor`, …).
203	pub fn capitalise_args(args: &str) -> String {
204	    match args.strip_prefix('{') {
205	        Some(rest) => format!(r#"{{"Id":1,"Name":"n","constructor":{{"Type":"t"}},"prototype":[],{rest}"#),
206	        None => args.to_owned(),
207	    }
208	}
