210	/// The chunks of one choice. The first chunk carries `role` (openai-node's `finalChatCompletion`
211	/// raises without one), as every real upstream sends it.
212	fn choice_records(c: usize, ch: &Choice, interleave: bool, unknown_type: Option<usize>, bad_args: Option<(Quirk, usize)>, capitalise: bool) -> Vec<Value> {
213	    let mut out = vec![chunk(json!([{"index":c,"delta":{"role":"assistant","content":ch.before.clone().unwrap_or_default()}}]))];
214	    let odd_call = unknown_type.filter(|_| c == 0 && !ch.calls.is_empty()).map(|k| k % ch.calls.len());
215	    let json_calls: Vec<usize> = (0..ch.calls.len()).filter(|i| ch.calls[*i].kind != CallKind::Custom).collect();
216	    let bad = bad_args.filter(|_| c == 0 && !json_calls.is_empty()).map(|(q, k)| (q, json_calls[k % json_calls.len()]));
217	    // Fragments per call: the first carries id/type/name.
218	    let per_call: Vec<Vec<Value>> = ch
219	        .calls
220	        .iter()
221	        .enumerate()
222	        .map(|(i, call)| {
223	            let ty = if odd_call == Some(i) {
224	                "web_search"
225	            } else if call.kind == CallKind::Custom {
226	                "custom"
227	            } else {
228	                "function"
229	            };
230	            let (body, args_key) = if call.kind == CallKind::Custom { ("custom", "input") } else { ("function", "arguments") };
231	            let args = if capitalise { capitalise_args(&call.args) } else { call.args.clone() };
232	            let args = match bad {
233	                Some((Quirk::TruncatedArgs, b)) if b == i => args[..args.len() - 1].to_owned(),
234	                Some((Quirk::ConcatenatedObjects, b)) if b == i => format!("{args}{{\"b\":2}}"),
235	                _ => args,
236	            };
237	            split(&args, call.pieces)
238	                .into_iter()
239	                .enumerate()
240	                .map(|(k, piece)| {
241	                    let delta = if call.kind == CallKind::Legacy {
242	                        if k == 0 {
243	                            json!({"function_call":{"name":call.name,"arguments":piece}})
244	                        } else {
245	                            json!({"function_call":{"arguments":piece}})
246	                        }
247	                    } else if k == 0 {
248	                        json!({"tool_calls":[{"index":i,"id":format!("call_{c}_{i}"),"type":ty,body:{"name":call.name,args_key:piece}}]})
249	                    } else {
250	                        json!({"tool_calls":[{"index":i,body:{args_key:piece}}]})
251	                    };
252	                    chunk(json!([{"index":c,"delta":delta}]))
253	                })
254	                .collect()
255	        })
256	        .collect();
257	    if interleave {
258	        let longest = per_call.iter().map(Vec::len).max().unwrap_or(0);
259	        for k in 0..longest {
260	            for frags in &per_call {
261	                if let Some(f) = frags.get(k) {
262	                    out.push(f.clone());
263	                }
264	            }
265	        }
266	    } else {
267	        out.extend(per_call.into_iter().flatten());
268	    }
269	    if let Some(t) = &ch.after {
270	        out.push(chunk(json!([{"index":c,"delta":{"content":t}}])));
271	    }
272	    let finish = if ch.calls.iter().any(|c| c.kind == CallKind::Legacy) {
273	        "function_call"
274	    } else if ch.calls.is_empty() {
275	        "stop"
276	    } else {
277	        "tool_calls"
278	    };
279	    out.push(chunk(json!([{"index":c,"delta":{},"finish_reason":finish}])));
280	    out
281	}
