283	fn choice_of(rec: &Value) -> Option<u64> {
284	    rec.pointer("/choices/0/index").and_then(Value::as_u64)
285	}
286	
287	fn is_tool_bearing(rec: &Value) -> bool {
288	    rec.get("choices")
289	        .and_then(Value::as_array)
290	        .is_some_and(|cs| cs.iter().any(|c| c.pointer("/delta/tool_calls").is_some() || c.pointer("/delta/function_call").is_some()))
291	}
