293	/// Whether `line` is a generated record whose only entry carries tool data for choice 0.
294	fn opens_call(line: &str) -> bool {
295	    let Some(Ok(v)) = line.strip_prefix("data: ").map(|d| serde_json::from_str::<Value>(d.trim_end())) else {
296	        return false;
297	    };
298	    let Some([c]) = v.get("choices").and_then(Value::as_array).map(Vec::as_slice) else { return false };
299	    c.get("index").and_then(Value::as_u64) == Some(0) && is_tool_bearing(&v)
300	}
