302	pub fn render_openai(s: &Scenario) -> Vec<u8> {
303	    let interleave = has(s, Quirk::Interleave).is_some();
304	    let bad_args = s.quirks.iter().copied().find(|(q, _)| matches!(q, Quirk::TruncatedArgs | Quirk::ConcatenatedObjects));
305	    let mut per: Vec<Vec<Value>> = s
306	        .choices
307	        .iter()
308	        .enumerate()
309	        .map(|(i, c)| choice_records(i, c, interleave, has(s, Quirk::UnknownType), bad_args, has(s, Quirk::CapitalisedArgKeys).is_some()))
310	        .collect();
311	    if has(s, Quirk::ReverseChoices).is_some() {
312	        per.reverse();
313	    }
314	    let mut recs: Vec<Value> = Vec::new();
315	    if interleave {
316	        let longest = per.iter().map(Vec::len).max().unwrap_or(0);
317	        for k in 0..longest {
318	            for p in &per {
319	                if let Some(r) = p.get(k) {
320	                    recs.push(r.clone());
321	                }
322	            }
323	        }
324	    } else {
325	        recs = per.into_iter().flatten().collect();
326	    }
327	    if let Some(at) = has(s, Quirk::MultiChoiceChunk) {
328	        // Merge record p with the first later record of another choice, that choice first.
329	        let p = at % recs.len();
330	        if let Some(q) = (p + 1..recs.len()).find(|q| choice_of(&recs[*q]) != choice_of(&recs[p])) {
331	            let later = recs.remove(q);
332	            let mut both = later["choices"].as_array().cloned().unwrap_or_default();
333	            both.extend(recs[p]["choices"].as_array().cloned().unwrap_or_default());
334	            recs[p]["choices"] = Value::Array(both);
335	        }
336	    }
337	    if let Some(at) = has(s, Quirk::DropObject) {
338	        let tool: Vec<usize> = (0..recs.len()).filter(|i| is_tool_bearing(&recs[*i])).collect();
339	        let i = if tool.is_empty() { at % recs.len() } else { tool[at % tool.len()] };
340	        if let Value::Object(m) = &mut recs[i] {
341	            m.remove("object");
342	        }
343	    }
344	    let mut lines: Vec<String> = recs.iter().map(|r| format!("data: {r}\n\n")).collect();
345	    let mut prefix = String::new();
346	    let mut suffix = String::new();
347	    for (q, at) in &s.quirks {
348	        let pos = at % (lines.len() + 1);
349	        let insert = |lines: &mut Vec<String>, rec: String| lines.insert(pos, format!("data: {rec}\n\n"));
350	        match q {
351	            Quirk::DuplicateDelta => insert(&mut lines, format!(r#"{{"choices":[{{"index":0,"delta":{{"tool_calls":[{}]}},"delta":{{"content":"x"}}}}]}}"#, hidden_entry(json!(0)))),
352	            Quirk::CaseFoldedKey => insert(&mut lines, format!(r#"{{"choices":[{{"index":0,"delta":{{"Tool_Calls":[{}]}}}}]}}"#, hidden_entry(json!(0)))),
353	            Quirk::ProtoKey => insert(&mut lines, format!(r#"{{"choices":[{{"index":0,"delta":{{"__proto__":{{"tool_calls":[{}]}}}}}}]}}"#, hidden_entry(json!(0)))),
354	            Quirk::FloatIndex => insert(&mut lines, chunk(json!([{"index":0,"delta":{"tool_calls":[hidden_entry(json!(0.0))]}}])).to_string()),
355	            Quirk::BoolIndex => insert(&mut lines, chunk(json!([{"index":0,"delta":{"tool_calls":[hidden_entry(json!(true))]}}])).to_string()),
356	            Quirk::NegativeIndex => insert(&mut lines, chunk(json!([{"index":0,"delta":{"tool_calls":[hidden_entry(json!(-1))]}}])).to_string()),
357	            Quirk::RepeatedName => insert(&mut lines, chunk(json!([{"index":0,"delta":{"tool_calls":[{"index":0,"function":{"name":"blocked_hidden","arguments":"CANARY-rn"}}]}}])).to_string()),
358	            Quirk::IndexGap => insert(&mut lines, chunk(json!([{"index":0,"delta":{"tool_calls":[hidden_entry(json!(9))]}}])).to_string()),
359	            Quirk::NaNRecord => insert(&mut lines, format!(r#"{{"x":NaN,"choices":[{{"index":0,"delta":{{"tool_calls":[{}]}}}}]}}"#, hidden_entry(json!(0)))),
360	            Quirk::EscapedKey => insert(
361	                &mut lines,
362	                r#"{"object":"chat.completion.chunk","choices":[{"index":0,"delta":{"tool\u005fcalls":[{"index":0,"id":"call_e","type":"function","function":{"name":"blocked_escaped","arguments":"CANARY-esc"}}]}}]}"#.to_owned(),
363	            ),
364	            Quirk::Oversized => insert(&mut lines, chunk(json!([{"index":0,"delta":{"tool_calls":[{"index":0,"function":{"arguments":format!("CANARY-big{}", "x".repeat(5000))}}]}}])).to_string()),
365	            Quirk::DuplicateChoiceIndex => insert(&mut lines, chunk(json!([{"index":0,"delta":{"content":"x"}},{"index":0,"delta":{"tool_calls":[hidden_entry(json!(0))]}}])).to_string()),
366	            Quirk::LaxLine => lines.insert(
367	                pos,
368	                format!(
369	                    "  data: {}\n\nData: {}\n\n",
370	                    chunk(json!([{"index":0,"delta":{"tool_calls":[hidden_entry(json!(0))]}}])),
371	                    chunk(json!([{"index":0,"delta":{"tool_calls":[hidden_entry(json!(0))]}}]))
372	                ),
373	            ),
374	            Quirk::NoDelta if at % 2 == 1 && lines.iter().any(|l| opens_call(l)) => {
375	                // R-B (spec § 5.2): a delta-less entry at position 1 of the record that opens a call.
376	                let i = lines.iter().position(|l| opens_call(l)).expect("checked");
377	                let mut v: Value = serde_json::from_str(lines[i].trim_start_matches("data: ").trim_end()).expect("a generated record");
378	                v["choices"].as_array_mut().expect("checked").push(json!({"index":1}));
379	                lines[i] = format!("data: {v}\n\n");
380	            }
381	            Quirk::NoChoicesKey | Quirk::NoDelta => {
