386	                    let rec = if *q == Quirk::NoChoicesKey { r#"{"object":"chat.completion.chunk","id":"q"}"#.to_owned() } else { chunk(json!([{"index":0}])).to_string() };
387	                    lines.insert(at, format!("data: {rec}\n\n"));
388	                }
389	            }
390	            Quirk::NullType if s.choices[0].calls.is_empty() && has(s, Quirk::ReverseChoices).is_none() => {
391	                let at = 1.min(lines.len());
392	                lines.insert(at, format!("data: {}\n\n", chunk(json!([{"index":0,"delta":{"tool_calls":[{"index":0,"type":null}]}}]))));
393	            }
394	            Quirk::NullType => insert(&mut lines, chunk(json!([{"index":0,"delta":{"tool_calls":[{"index":0,"type":null,"function":{"name":"blocked_hidden","arguments":"CANARY-nt"}}]}}])).to_string()),
