396	            Quirk::ContentDeltaType => insert(&mut lines, {
397	                let mut r = chunk(json!([{"index":0,"delta":{"tool_calls":[{"index":0,"function":{"arguments":"zz"}}]}}]));
398	                r["type"] = json!("content.delta");
399	                r.to_string()
400	            }),
401	            Quirk::ArrayOutsideToolCalls => {
402	                let delta = |list: Value| match at % 3 {
403	                    0 => json!({"foo":list}),
404	                    1 => json!({"tool_calls":[{"index":0,"function":{"arguments":""},"x":list}]}),
405	                    _ => json!({"tool_calls":[{"index":0,"function":{"arguments":"","x":list}}]}),
406	                };
407	                let two = [json!([{"index":0}]), json!([1])].map(|l| format!("data: {}\n\n", chunk(json!([{"index":0,"delta":delta(l)}]))));
408	                // As for NoChoicesKey: keep the raising records off the BOM-prefixed line 0 (spec § 9).
409	                let at = if pos == 0 && has(s, Quirk::Bom).is_some() { 1.min(lines.len()) } else { pos };
410	                lines.splice(at..at, two);
411	            }
412	            Quirk::FunctionCallKey => {
413	                let two = [json!("s"), json!(1)].map(|x| format!("data: {}\n\n", chunk(json!([{"index":0,"delta":{"function_call":{"arguments":"","x":x}}}]))));
414	                lines.splice(pos..pos, two);
415	            }
416	            Quirk::UnknownFields => lines.insert(pos, "id: 7\nretry: 10\nfoo: bar\n".to_owned()),
417	            Quirk::Comments => lines.insert(pos, ": hello\n: data: {\"x\":\"CANARY-comment\"}\n".to_owned()),
418	            Quirk::EventLine => lines.insert(pos, "event: message\n".to_owned()),
419	            Quirk::Bom => prefix = "\u{feff}".to_owned(),
420	            Quirk::AfterDone => suffix = format!("data: {}\n\n", chunk(json!([{"index":0,"delta":{"tool_calls":[hidden_entry(json!(0))]}}]))),
421	            Quirk::NoFinalBlank | Quirk::JsonBody | Quirk::Interleave | Quirk::DropObject | Quirk::MultiChoiceChunk | Quirk::UnknownType | Quirk::ReverseChoices | Quirk::TruncatedArgs | Quirk::ConcatenatedObjects | Quirk::CapitalisedArgKeys => {}
422	        }
423	    }
424	    let mut body = format!("{prefix}{}data: [DONE]\n\n{suffix}", lines.concat());
425	    if has(s, Quirk::NoFinalBlank).is_some() {
426	        body.truncate(body.trim_end_matches('\n').len());
427	    }
428	    if has(s, Quirk::JsonBody).is_some() {
429	        body = json!({"choices":[{"index":0,"message":{"tool_calls":[{"id":"c","type":"function","function":{"name":"blocked_json","arguments":"CANARY-json"}}]}}]}).to_string();
430	    }
431	    body.into_bytes()
432	}
