518	pub fn render_anthropic(s: &AnthropicScenario) -> Vec<u8> {
519	    let mut evs: Vec<Value> = vec![json!({"type":"message_start","message":{"id":"msg_g","type":"message","role":"assistant","content":[],"model":"c","usage":{"input_tokens":1,"output_tokens":1}}})];
520	    let tools: Vec<usize> = s.blocks.iter().enumerate().filter(|(_, b)| matches!(b, Block::Tool { .. })).map(|(i, _)| i).collect();
521	    let truncated = ahas(s, AQuirk::TruncatedArgs).filter(|_| !tools.is_empty()).map(|k| tools[k % tools.len()]);
522	    // With Interleave, block k's stop is deferred until after block k+1's start.
523	    let interleave_at = ahas(s, AQuirk::Interleave).filter(|_| s.blocks.len() > 1).map(|k| k % (s.blocks.len() - 1));
524	    let mut deferred: Option<Value> = None;
525	    for (i, b) in s.blocks.iter().enumerate() {
526	        match b {
527	            Block::Text(t) => {
528	                evs.push(json!({"type":"content_block_start","index":i,"content_block":{"type":"text","text":""}}));
529	                if let Some(d) = deferred.take() {
530	                    evs.push(d);
531	                }
532	                evs.push(json!({"type":"content_block_delta","index":i,"delta":{"type":"text_delta","text":t}}));
533	            }
534	            Block::Tool { name, args, pieces } => {
535	                evs.push(json!({"type":"content_block_start","index":i,"content_block":{"type":"tool_use","id":format!("toolu_{i}"),"name":name,"input":{}}}));
536	                if let Some(d) = deferred.take() {
537	                    evs.push(d);
538	                }
539	                let args = if ahas(s, AQuirk::CapitalisedArgKeys).is_some() { capitalise_args(args) } else { args.clone() };
540	                let mut parts = split(&args, *pieces);
541	                if truncated == Some(i) {
542	                    let last = parts.pop().unwrap_or_default();
543	                    parts.push(last[..last.len().saturating_sub(1)].to_owned());
544	                }
545	                for p in parts {
546	                    evs.push(json!({"type":"content_block_delta","index":i,"delta":{"type":"input_json_delta","partial_json":p}}));
547	                }
548	            }
549	            Block::Server => {
550	                evs.push(json!({"type":"content_block_start","index":i,"content_block":{"type":"server_tool_use","id":format!("srv_{i}"),"name":"web_search","input":{}}}));
551	                if let Some(d) = deferred.take() {
552	                    evs.push(d);
553	                }
554	                evs.push(json!({"type":"content_block_delta","index":i,"delta":{"type":"input_json_delta","partial_json":"{\"q\":\"x\"}"}}));
555	            }
556	        }
557	        let stop = json!({"type":"content_block_stop","index":i});
558	        if interleave_at == Some(i) {
559	            deferred = Some(stop);
560	        } else {
561	            evs.push(stop);
562	        }
563	    }
564	    let any_tool = !tools.is_empty();
565	    evs.push(json!({"type":"message_delta","delta":{"stop_reason": if any_tool { "tool_use" } else { "end_turn" },"stop_sequence":null},"usage":{"output_tokens":1}}));
566	    evs.push(json!({"type":"message_stop"}));
567	    let no_events = ahas(s, AQuirk::NoEventLines).is_some();
568	    let mut frames: Vec<String> = evs
569	        .iter()
570	        .map(|e| {
571	            if no_events {
572	                format!("data: {e}\n\n")
573	            } else {
574	                format!("event: {}\ndata: {e}\n\n", e["type"].as_str().unwrap())
575	            }
576	        })
577	        .collect();
578	    let hidden_start = |idx: usize, input: Value| json!({"type":"content_block_start","index":idx,"content_block":{"type":"tool_use","id":"toolu_h","name":"blocked_hidden","input":input}});
579	    let mut prefix = String::new();
580	    let mut suffix = String::new();
581	    for (q, at) in &s.quirks {
582	        let pos = 1 + at % frames.len().max(1);
583	        let pos = pos.min(frames.len().saturating_sub(1));
584	        match q {
585	            AQuirk::EventMismatch => frames.insert(pos, format!("event: ping\ndata: {}\n\n", hidden_start(s.blocks.len(), json!({"v":"CANARY-em"})))),
586	            AQuirk::PrefilledInput => frames.insert(pos, format!("event: content_block_start\ndata: {}\n\n", hidden_start(s.blocks.len(), json!({"v":"CANARY-pi"})))),
587	            AQuirk::PrefilledMessage => {
588	                frames[0] = format!(
589	                    "event: message_start\ndata: {}\n\n",
590	                    json!({"type":"message_start","message":{"content":[{"type":"tool_use","id":"t","name":"blocked_hidden","input":{"v":"CANARY-pm"}}]}})
591	                )
592	            }
593	            AQuirk::IndexReuse => frames.insert(
594	                pos,
595	                format!(
596	                    "event: content_block_start\ndata: {}\n\n",
597	                    json!({"type":"content_block_start","index":0,"content_block":{"type":"tool_use","id":"toolu_r","name":"blocked_reuse","input":{}}})
598	                ),
599	            ),
600	            AQuirk::DuplicateKey => frames.insert(
601	                pos,
602	                format!(
603	                    "event: content_block_delta\ndata: {}\n\n",
604	                    r#"{"type":"content_block_delta","index":0,"delta":{"type":"input_json_delta","partial_json":"CANARY-dup"},"delta":{"type":"text_delta","text":"x"}}"#
605	                ),
606	            ),
607	            AQuirk::Oversized => frames.insert(
608	                pos,
609	                format!(
610	                    "event: content_block_delta\ndata: {}\n\n",
611	                    json!({"type":"content_block_delta","index":0,"delta":{"type":"input_json_delta","partial_json":format!("CANARY-big{}", "x".repeat(5000))}})
612	                ),
613	            ),
614	            AQuirk::NegativeIndex => frames.insert(
615	                pos,
616	                format!(
617	                    "event: content_block_delta\ndata: {}\n\n",
618	                    json!({"type":"content_block_delta","index":-1,"delta":{"type":"input_json_delta","partial_json":"\"CANARY-neg\""}})
619	                ),
620	            ),
621	            AQuirk::DeltaAfterStop => frames.insert(
622	                frames.len().saturating_sub(2).max(1),
623	                format!(
624	                    "event: content_block_delta\ndata: {}\n\n",
625	                    json!({"type":"content_block_delta","index":0,"delta":{"type":"input_json_delta","partial_json":"\"CANARY-late\""}})
626	                ),
627	            ),
628	            AQuirk::Bom => prefix = "\u{feff}".to_owned(),
629	            AQuirk::AfterStop => suffix = format!("event: content_block_start\ndata: {}\n\n", hidden_start(s.blocks.len(), json!({}))),
630	            AQuirk::NoEventLines | AQuirk::Interleave | AQuirk::TruncatedArgs | AQuirk::CapitalisedArgKeys => {}
631	        }
632	    }
633	    format!("{prefix}{}{suffix}", frames.concat()).into_bytes()
