57	type Hash = [u8; 32];
58	
59	fn finish(h: &Sha256) -> Hash {
60	    let mut out = [0; 32];
61	    out.copy_from_slice(&h.clone().finalize());
62	    out
63	}
64	
65	fn hash_str(s: &str) -> Hash {
66	    let mut h = Sha256::new();
67	    h.update(s.as_bytes());
68	    finish(&h)
69	}
70	
71	fn feed_str(h: &mut Sha256, s: &str) {
72	    h.update((s.len() as u64).to_be_bytes());
73	    h.update(s.as_bytes());
74	}
75	
76	/// Feed a JSON value so that two values hash equal exactly when they are equal as JSON values
77	/// (`Value::eq`): object keys in sorted order, so key order is no difference.
78	fn feed_value(h: &mut Sha256, v: &Value) {
79	    match v {
80	        Value::Null => h.update([0]),
81	        Value::Bool(b) => h.update([1, u8::from(*b)]),
82	        Value::Number(n) => {
83	            h.update([2]);
84	            // `-0.0 == 0.0` as a `Value`, but the two print differently.
85	            let text = if n.is_f64() && n.as_f64() == Some(0.0) { "0.0".to_owned() } else { n.to_string() };
86	            feed_str(h, &text);
87	        }
88	        Value::String(s) => {
89	            h.update([3]);
90	            feed_str(h, s);
91	        }
92	        Value::Array(a) => {
93	            h.update([4]);
94	            h.update((a.len() as u64).to_be_bytes());
95	            a.iter().for_each(|x| feed_value(h, x));
96	        }
97	        Value::Object(o) => {
98	            h.update([5]);
99	            h.update((o.len() as u64).to_be_bytes());
100	            let mut keys: Vec<&String> = o.keys().collect();
101	            keys.sort();
102	            for k in keys {
103	                feed_str(h, k);
104	                feed_value(h, &o[k.as_str()]);
105	            }
106	        }
107	    }
108	}
109	
110	fn hash_value(v: &Value) -> Hash {
111	    let mut h = Sha256::new();
112	    feed_value(&mut h, v);
113	    finish(&h)
