149	/// The call of one client-run Responses item, by the § 5 table. Shared by the stream (the `done`
150	/// item) and the body path (an `output[]` item).
151	///
152	/// `namespace` is the `namespace` of a function or custom call (when present) and the
153	/// `server_label` of an `mcp_approval_request` (§ 5, ruling T4a).
154	/// `id` is the `call_id`, or the item `id` for `mcp_approval_request`. A server `tool_search_call`
155	/// may have no `call_id`. Kind `Other` takes the `call_id` when the item has one, else the item
156	/// `id` (§ 5 gives no row for it). `arguments` is `arguments` for a function (`""` becomes `"{}"`),
157	/// `input` for a custom call, and for every other kind the item as compact JSON in its own key
158	/// order, with `status` removed. The item's numbers must be exact (`check_numbers`, § 7.1).
159	pub(crate) fn tool_call(position: u32, item: &Map<String, Value>, kind: ToolCallKind) -> Result<ToolCall, Malformed> {
160	    item.values().try_for_each(check_numbers)?;
161	    let (namespace, name) = name_of(item, kind)?;
162	    let id = match kind {
163	        ToolCallKind::McpApprovalRequest => Some(text_of(item, "id")?),
164	        ToolCallKind::ToolSearch => opt_str(item.get("call_id"), "call_id")?,
165	        ToolCallKind::Other => match opt_str(item.get("call_id"), "call_id")? {
166	            Some(c) => Some(c),
167	            None => opt_str(item.get("id"), "id")?,
168	        },
169	        _ => Some(text_of(item, "call_id")?),
170	    };
171	    let arguments = match kind {
172	        ToolCallKind::Function => {
173	            let a = text_of(item, "arguments")?;
174	            if a.is_empty() { "{}".to_owned() } else { a }
175	        }
176	        ToolCallKind::Custom => text_of(item, "input")?,
177	        _ => {
178	            let stripped: Map<String, Value> = item.iter().filter(|(k, _)| *k != "status").map(|(k, v)| (k.clone(), v.clone())).collect();
179	            serde_json::to_string(&Value::Object(stripped)).expect("a Value always serializes")
180	        }
181	    };
182	    Ok(ToolCall {
183	        choice: 0,
184	        position,
185	        id,
186	        name,
187	        namespace,
188	        kind,
189	        arguments,
190	    })
191	}
