231	/// A delta stream: the running hash of the deltas and the hash of its `*.done` text.
232	#[derive(Default)]
233	struct Text {
234	    deltas: Sha256,
235	    done: Option<Hash>,
236	    /// Any delta or `*.done` event arrived.
237	    touched: bool,
238	    /// A delta after the `*.done` event, a second `*.done` event, or a value that is no string.
239	    broken: bool,
240	}
241	
242	impl Text {
243	    fn delta(&mut self, d: Option<&Value>) -> bool {
244	        self.touched = true;
245	        match d {
246	            Some(Value::String(s)) if self.done.is_none() => self.deltas.update(s.as_bytes()),
247	            _ => self.broken = true,
248	        }
249	        !self.broken
250	    }
251	
252	    /// Record the `*.done` text. `false` when the stream is broken or the text is not the deltas.
253	    fn done(&mut self, t: Option<&Value>) -> bool {
254	        self.touched = true;
255	        match t {
256	            Some(Value::String(s)) if self.done.is_none() => self.done = Some(hash_str(s)),
257	            _ => self.broken = true,
258	        }
259	        !self.broken && self.done == Some(finish(&self.deltas))
260	    }
261	
262	    /// The deltas, and the `*.done` text when one arrived, both equal `value`.
263	    fn agrees(&self, value: &str) -> bool {
264	        let h = hash_str(value);
265	        !self.broken && finish(&self.deltas) == h && self.done.is_none_or(|d| d == h)
266	    }
267	}
