299	/// R8: an object with a string `type` and a non-empty string `id`. The identity fields and
300	/// `server_label` are strings or `null` where present, and none is longer than
301	/// `MAX_IDENTIFIER_BYTES`.
302	pub(crate) fn item_shape(v: Option<&Value>) -> Result<(&Map<String, Value>, &str, &str), Deviation> {
303	    let bad = Deviation("item_shape");
304	    let Some(Value::Object(m)) = v else { return Err(bad) };
305	    let Some(Value::String(ty)) = m.get("type") else { return Err(bad) };
306	    let Some(Value::String(id)) = m.get("id") else { return Err(bad) };
307	    if id.is_empty() {
308	        return Err(bad);
309	    }
310	    let named = IDENTITY.iter().chain(&["server_label"]).filter_map(|k| m.get(*k));
311	    let mut long = false;
312	    for v in named {
313	        match v {
314	            Value::Null => {}
315	            Value::String(s) => long |= s.len() > MAX_IDENTIFIER_BYTES,
316	            _ => return Err(bad),
317	        }
318	    }
319	    if long {
320	        return Err(Deviation("long_identifier"));
321	    }
322	    Ok((m, ty, id))
323	}
