325	/// The subset rule (§ 6.4, A2): every field of `added`, at any depth, except the top-level
326	/// `status`, is `null`, `""`, `[]` or equal to the same field of `done`, and `done` has every
327	/// field that `added` has. An object field follows the rule inside; an array is `[]` or equal.
328	fn subset(added: &Map<String, Value>, done: &Map<String, Value>, top: bool) -> bool {
329	    added.iter().all(|(k, a)| {
330	        if top && k == "status" {
331	            return true;
332	        }
333	        let Some(d) = done.get(k) else { return false };
334	        match a {
335	            Value::Null => true,
336	            Value::String(s) if s.is_empty() => true,
337	            Value::Array(x) if x.is_empty() => true,
338	            Value::Object(ao) => matches!(d, Value::Object(dobj) if subset(ao, dobj, false)),
339	            _ => a == d,
340	        }
341	    })
342	}
