362	/// R13 per command event. Indexes appear in order, and a command ends before the next starts.
363	fn shell_event(commands: &mut Vec<Command>, ty: &str, ev: &Map<String, Value>) -> Result<(), Deviation> {
364	    let bad = Deviation("shell_command_mismatch");
365	    let i = index_of(ev.get("command_index")).ok_or(bad)? as usize;
366	    let text = |k: &str| match ev.get(k) {
367	        Some(Value::String(s)) => Ok(s.as_str()),
368	        _ => Err(bad),
369	    };
370	    if ty == "response.shell_call_command.added" {
371	        if i != commands.len() || commands.last().is_some_and(|c| c.done.is_none()) {
372	            return Err(bad);
373	        }
374	        let mut h = Sha256::new();
375	        h.update(text("command")?.as_bytes());
376	        commands.push(Command { text: h, done: None });
377	        return Ok(());
378	    }
379	    if i + 1 != commands.len() {
380	        return Err(bad);
381	    }
382	    let c = commands.last_mut().filter(|c| c.done.is_none()).ok_or(bad)?;
383	    if ty == "response.shell_call_command.delta" {
384	        c.text.update(text("delta")?.as_bytes());
385	    } else {
386	        let h = hash_str(text("command")?);
387	        if finish(&c.text) != h {
388	            return Err(bad);
389	        }
390	        c.done = Some(h);
391	    }
392	    Ok(())
393	}
