526	    /// Apply one classified event (`ty` is its `data.type`). `keepalive` and `error` are exempt
527	    /// (§ 6.4). A record after the terminal event changes nothing: the stream drops and counts it
528	    /// (R3, ruling F8).
529	    pub(crate) fn accept(&mut self, ty: &'static str, v: &Value) -> Result<Effect, Deviation> {
530	        if let Some(d) = self.failed {
531	            return Err(d);
532	        }
533	        let r = self.step(ty, v);
534	        if let Err(d) = r {
535	            self.failed = Some(d);
536	        }
537	        r
538	    }
539	
540	    fn step(&mut self, ty: &'static str, v: &Value) -> Result<Effect, Deviation> {
541	        let scope = scope_of(ty);
542	        if matches!(scope, Scope::Keepalive | Scope::Error) || self.ended {
543	            return Ok(Effect::other());
544	        }
545	        let Value::Object(ev) = v else { return Err(Deviation("not_object")) };
546	        if !self.started && ty != "response.created" {
547	            return Err(Deviation("first_not_created"));
548	        }
549	        if self.started && ty == "response.created" {
550	            return Err(Deviation("repeated_created"));
551	        }
552	        self.sequence(ev)?;
553	        match scope {
554	            Scope::Lifecycle => {
555	                let resp = self.response_of(ev, ty == "response.created")?;
556	                if !matches!(resp.get("output"), Some(Value::Array(a)) if a.is_empty()) {
557	                    return Err(Deviation("early_output"));
558	                }
559	                self.started = true;
560	                Ok(Effect::other())
561	            }
562	            Scope::Terminal => self.terminal(ev),
563	            Scope::ItemAdded => self.added(ev),
564	            Scope::ItemDone => self.done(ev),
565	            Scope::Item(item_type) => self.middle(ty, item_type, v, ev),
566	            Scope::ResponseLevel | Scope::Keepalive | Scope::Error => Ok(Effect::other()),
567	        }
568	    }
569	
570	    /// R7: an integer that strictly increases, on every event or on none.
571	    fn sequence(&mut self, ev: &Map<String, Value>) -> Result<(), Deviation> {
572	        let bad = Deviation("sequence_number");
573	        let n = match ev.get("sequence_number") {
574	            None => None,
575	            Some(Value::Number(n)) if n.is_u64() => n.as_u64(),
576	            Some(_) => return Err(bad),
577	        };
578	        match (*self.numbered.get_or_insert(n.is_some()), n) {
579	            (true, Some(n)) if self.last_number.is_none_or(|l| n > l) => {
580	                self.last_number = Some(n);
581	                Ok(())
582	            }
583	            (false, None) => Ok(()),
584	            _ => Err(bad),
585	        }
586	    }
587	
588	    /// R1: the `response` object, whose `id` is the same on every lifecycle and terminal event.
589	    fn response_of<'a>(&mut self, ev: &'a Map<String, Value>, created: bool) -> Result<&'a Map<String, Value>, Deviation> {
590	        let bad = Deviation(if created && self.response_id.is_none() { "first_not_created" } else { "response_id_changed" });
591	        let Some(Value::Object(resp)) = ev.get("response") else { return Err(bad) };
592	        let Some(Value::String(id)) = resp.get("id") else { return Err(bad) };
593	        match &self.response_id {
594	            None => self.response_id = Some(id.clone()),
595	            Some(prev) if prev == id => {}
596	            Some(_) => return Err(Deviation("response_id_changed")),
597	        }
598	        Ok(resp)
599	    }
600	
601	    /// R3, R9, R10, and R15 for a client-run item with no `done`.
602	    fn terminal(&mut self, ev: &Map<String, Value>) -> Result<Effect, Deviation> {
603	        let resp = self.response_of(ev, false)?;
604	        let Some(Value::Array(output)) = resp.get("output") else {
605	            return Err(Deviation("terminal_output_missing"));
606	        };
607	        let mismatch = Deviation("terminal_output_mismatch");
608	        if output.len() != self.items.len() {
609	            return Err(mismatch);
610	        }
611	        for (seen, v) in self.items.iter().zip(output) {
612	            let Value::Object(item) = v else { return Err(mismatch) };
613	            if identity(item) != seen.identity {
614	                return Err(Deviation("item_identity_changed"));
615	            }
616	            if seen.done_hash.is_some_and(|h| h != hash_value(v)) {
617	                return Err(mismatch);
618	            }
619	        }
620	        if let Some(open) = self.open.take() {
621	            if matches!(open.class, ItemClass::ClientRun(_)) {
622	                self.truncated = true;
623	            }
624	            self.held -= open.added.as_ref().map_or(0, raw_len);
625	        }
626	        self.ended = true;
627	        Ok(Effect { terminal: true, ..Effect::other() })
628	    }
629	
630	    /// R4, R5, R8 at `response.output_item.added`.
631	    fn added(&mut self, ev: &Map<String, Value>) -> Result<Effect, Deviation> {
632	        let value = ev.get("item");
633	        let (item, ty, id) = item_shape(value)?;
634	        let next = u32::try_from(self.items.len()).unwrap_or(u32::MAX);
635	        let index = index_of(ev.get("output_index")).ok_or(Deviation("index_order"))?;
636	        if index < next {
637	            return Err(Deviation("index_reused"));
638	        }
639	        if index > next {
640	            return Err(Deviation("index_order"));
641	        }
642	        if self.open.is_some() {
643	            return Err(Deviation("item_interleaved"));
644	        }
645	        if id.starts_with(RESERVED_ID_PREFIX) {
646	            return Err(Deviation("reserved_id"));
647	        }
648	        if self.ids.contains(id) {
649	            return Err(Deviation("duplicate_id"));
650	        }
651	        let call_id = match item.get("call_id") {
652	            Some(Value::String(c)) => Some(c),
653	            _ => None,
654	        };
655	        if call_id.is_some_and(|c| self.call_ids.contains(c)) {
656	            return Err(Deviation("duplicate_call_id"));
657	        }
658	        self.ids.insert(id.to_owned());
659	        if let Some(c) = call_id {
660	            self.call_ids.insert(c.clone());
661	        }
662	        let class = item_class(ty);
663	        let mut effect = Effect {
664	            frame: ItemFrame::Added,
665	            ..Effect::other()
666	        };
667	        let mut added = None;
668	        match class {
669	            ItemClass::ClientRun(kind) => {
670	                effect.item = Some(index);
671	                if !self.hold_open {
672	                    self.hold_open = true;
673	                    effect.opened = true;
674	                }
675	                self.client.push(index);
676	                // The name the calls not assembled yet are known by (a `BlockAll` report).
677	                let name = match name_of(item, kind) {
678	                    Ok((Some(ns), name)) => format!("{ns}.{name}"),
679	                    Ok((None, name)) => name,
680	                    Err(_) => kind.as_str().to_owned(),
681	                };
682	                self.names.push((index, name));
683	                let v = value.cloned().expect("item_shape found the item");
684	                self.held += raw_len(&v);
685	                added = Some(v);
686	            }
687	            ItemClass::ProviderRun => {
688	                effect.report = Some(ReportEntry {
689	                    choice: 0,
690	                    position: index,
691	                    name: ty.to_owned(),
692	                    decision: ReportDecision::Unenforceable,
693	                    basis: None,
694	                    code: None,
695	                });
696	            }
697	            ItemClass::Content => {}
698	        }
699	        self.items.push(Seen {
700	            identity: identity(item),
701	            done: false,
702	            done_hash: None,
703	        });
704	        self.open = Some(Open {
705	            index,
706	            ty: ty.to_owned(),
707	            id: id.to_owned(),
708	            class,
709	            added,
710	            text: Text::default(),
711	            commands: Vec::new(),
712	        });
713	        Ok(effect)
714	    }
