716	    /// R6 and R16: the event's `output_index` is the open item's.
717	    fn locate(&self, ev: &Map<String, Value>) -> Result<u32, Deviation> {
718	        let index = index_of(ev.get("output_index")).ok_or(Deviation("wrong_item_index"))?;
719	        if self.open.as_ref().is_some_and(|o| o.index == index) {
720	            return Ok(index);
721	        }
722	        if self.items.get(index as usize).is_some_and(|s| s.done) {
723	            return Err(Deviation("event_after_done"));
724	        }
725	        Err(Deviation("wrong_item_index"))
726	    }
727	
728	    /// An item-scoped event between `added` and `done` (R6, R11–R14 ordering, R16).
729	    fn middle(&mut self, ty: &'static str, item_type: &'static str, v: &Value, ev: &Map<String, Value>) -> Result<Effect, Deviation> {
730	        let index = self.locate(ev)?;
731	        let open = self.open.as_mut().expect("locate found the open item");
732	        // Ruling T3a: a content part belongs to the item type its part names.
733	        let expected = if ty.starts_with("response.content_part.") {
734	            content_part_item(v).map_err(|_| Deviation("event_item_type"))?
735	        } else {
736	            item_type
737	        };
738	        if open.ty != expected {
739	            return Err(Deviation("event_item_type"));
740	        }
741	        // `response.shell_call_command.*` is the one item-scoped family with no `item_id`.
742	        let no_item_id = ty.starts_with("response.shell_call_command.");
743	        match ev.get("item_id") {
744	            Some(Value::String(s)) if *s == open.id => {}
745	            None if no_item_id => {}
746	            _ => return Err(Deviation("item_id_mismatch")),
747	        }
748	        // Function and custom streams are judged at `done`, where R15 can take precedence (A3).
749	        // An apply-patch diff and a shell command are judged here too.
750	        let diff_ok = match ty {
751	            "response.function_call_arguments.delta" | "response.custom_tool_call_input.delta" => {
752	                open.text.delta(ev.get("delta"));
753	                true
754	            }
755	            "response.function_call_arguments.done" => {
756	                open.text.done(ev.get("arguments"));
757	                true
758	            }
759	            "response.custom_tool_call_input.done" => {
760	                open.text.done(ev.get("input"));
761	                true
762	            }
763	            "response.apply_patch_call_operation_diff.delta" => open.text.delta(ev.get("delta")),
764	            "response.apply_patch_call_operation_diff.done" => open.text.done(ev.get("diff")),
765	            _ if no_item_id => {
766	                shell_event(&mut open.commands, ty, ev)?;
767	                true
768	            }
769	            _ => true,
770	        };
771	        if !diff_ok {
772	            return Err(Deviation("diff_mismatch"));
773	        }
774	        let client = matches!(open.class, ItemClass::ClientRun(_));
775	        Ok(Effect {
776	            frame: ItemFrame::Middle,
777	            item: client.then_some(index),
778	            ..Effect::other()
779	        })
780	    }
781	
782	    /// R9, R11–R15 and the subset rule at `response.output_item.done`.
783	    fn done(&mut self, ev: &Map<String, Value>) -> Result<Effect, Deviation> {
784	        let value = ev.get("item");
785	        let (item, item_type, _) = item_shape(value)?;
786	        let index = self.locate(ev)?;
787	        if identity(item) != self.items[index as usize].identity {
788	            return Err(Deviation("item_identity_changed"));
789	        }
790	        let open = self.open.take().expect("locate found the open item");
791	        let mut client = false;
792	        if let ItemClass::ClientRun(kind) = open.class {
793	            client = true;
794	            let added_value = open.added.as_ref().expect("a client-run item keeps its added item");
795	            let added = added_value.as_object().expect("item_shape checked the added item");
796	            // R15: a `done` whose `status` is not `"completed"` is a truncation. An absent `status`
797	            // is one too, except for an item type whose model has no `status` field (T4b).
798	            let completed = is_completed(item, item_type);
799	            check_client(kind, &open, added, item, completed)?;
800	            if !subset(added, item, true) {
801	                return Err(Deviation("added_done_differ"));
802	            }
803	            let call = tool_call(index, item, kind).map_err(|m| Deviation(if m.0 == "lossy_number" { "lossy_number" } else { "item_shape" }))?;
804	            if !completed {
805	                self.truncated = true;
806	            }
807	            self.held -= raw_len(added_value);
808	            if let Some(n) = self.names.last_mut() {
809	                *n = (index, call.display_name());
810	            }
811	            if !self.overflowed {
812	                self.held += call.arguments.len();
813	                self.calls.push(call);
814	                if self.held > self.cap {
815	                    // 749 D13: an outgrown hold keeps nothing and is never decided.
816	                    self.overflowed = true;
817	                    self.held -= std::mem::take(&mut self.calls).iter().map(|c| c.arguments.len()).sum::<usize>();
818	                }
819	            }
820	            self.items[index as usize].done_hash = value.map(hash_value);
821	        }
822	        self.items[index as usize].done = true;
823	        Ok(Effect {
824	            frame: ItemFrame::Done,
825	            item: client.then_some(index),
826	            ..Effect::other()
827	        })
828	    }
829	
830	    /// Whether the response hold opened: a client-run item was added (D10). It stays `true`.
831	    pub(crate) fn hold_open(&self) -> bool {
832	        self.hold_open
833	    }
834	
835	    /// R15: a client-run `done` was not `"completed"`, or the terminal event arrived while a
836	    /// client-run item had no `done`. (`[DONE]` and EOF before the terminal are the stream's.)
837	    pub(crate) fn truncated(&self) -> bool {
838	        self.truncated
839	    }
840	
841	    /// The calls outgrew the cap and were dropped: the hold must never be decided as allowed on
842	    /// the strength of [`Assembly::hold_calls`], which is then empty (749 D13).
843	    pub(crate) fn overflowed(&self) -> bool {
844	        self.overflowed
845	    }
846	
847	    /// The terminal event arrived (R3). Every later record but `[DONE]` is dropped and counted.
848	    pub(crate) fn ended(&self) -> bool {
849	        self.ended
850	    }
851	
852	    /// The end-of-stream rule of the response hold, read at the terminal event, at `[DONE]` and at
853	    /// EOF: the hold opened and cannot be decided as complete. It is cut when no terminal event
854	    /// arrived (R3; also R15 when a client-run item has no `done`), when the stream is truncated
855	    /// (R15), or when the calls outgrew the cap (749 D13, ruling T4d). A cut hold is never decided
856	    /// on [`Assembly::hold_calls`]: the interceptor applies `on_failure` to it.
857	    pub(crate) fn hold_cut(&self) -> bool {
858	        self.hold_open && (!self.ended || self.truncated() || self.overflowed())
859	    }
860	
861	    /// The completed calls, in `output_index` order. Moves them out. Empty after an overflow.
862	    pub(crate) fn hold_calls(&mut self) -> Vec<ToolCall> {
863	        let calls = std::mem::take(&mut self.calls);
864	        self.held -= calls.iter().map(|c| c.arguments.len()).sum::<usize>();
865	        calls
866	    }
