1	// SPDX-License-Identifier: Apache-2.0
2	//! Rust models of how the Responses API clients turn stream bytes into tool calls (SMA-769
3	//! § 10.1).
4	//!
5	//! Each model reads the interceptor's OUTPUT and derives the calls from EVERY surface its SDK
6	//! exposes, because the SDKs read a call from different events (§ 3.2, R-a). One call that two
7	//! surfaces show the same way is one model call ([`dedupe`]); two surfaces that show it
8	//! differently are two calls, and only one of them can match the decided call.
9	//!
10	//! A model stops at the first point where its SDK raises (`Run::error`), with the calls the
11	//! client saw up to that point. A model reproduces a raise only where the source makes it
12	//! certain. A model that raises later than its SDK sees more calls, which is stricter; a model
13	//! that raised earlier would see fewer calls, which would be more lenient.
14	//!
15	//! An `output_item.added` item is never a call in these models: it is a partial view by design
16	//! (spec § 15, A2 and A5).
17	
18	use std::collections::{BTreeMap, BTreeSet, HashMap, HashSet};
19	
20	use paigasus_gateway_core::ToolCall;
21	use serde_json::{Map, Value, json};
22	
23	use super::oracle::{ModelCall, Run, Runner, js_truthy, lc_parse_partial_json, node_events, py_events, py_get, py_int, py_truthy, responses_kind_of};
24	
25	/// The models of the Responses clients, in the order [`super::oracle::check_i1`] runs them.
26	pub const RESPONSES_RUNNERS: &[(&str, Runner)] = &[
27	    ("openai-python-responsestream", run_python_stream),
28	    ("openai-python-raw", run_python_raw),
29	    ("openai-node-responses", run_node),
30	    ("langchain-responses", run_langchain),
31	];
32	
33	const ADDED: &str = "response.output_item.added";
34	const DONE: &str = "response.output_item.done";
35	const LIFECYCLE: [&str; 6] = [
36	    "response.created",
37	    "response.queued",
38	    "response.in_progress",
39	    "response.completed",
40	    "response.failed",
41	    "response.incomplete",
42	];
43	const INTERIM: [&str; 3] = ["response.created", "response.queued", "response.in_progress"];
44	const TERMINAL: [&str; 3] = ["response.completed", "response.failed", "response.incomplete"];
45	
46	/// The item types that no client runs: tool-free content and provider-run items (spec § 6.2).
47	const NOT_RUN_BY_CLIENT: [&str; 17] = [
48	    "message",
49	    "reasoning",
50	    "compaction",
51	    "web_search_call",
52	    "file_search_call",
53	    "code_interpreter_call",
54	    "image_generation_call",
55	    "mcp_call",
56	    "mcp_list_tools",
57	    "program",
58	    "program_output",
59	    "additional_tools",
60	    "tool_search_output",
61	    "shell_call_output",
62	    "local_shell_call_output",
63	    "computer_call_output",
64	    "apply_patch_call_output",
65	];
66	
67	/// The model kind of an item type, or `None` for an item that no client runs.
68	fn kind_of_type(ty: &str) -> Option<&'static str> {
69	    if NOT_RUN_BY_CLIENT.contains(&ty) {
70	        return None;
71	    }
72	    Some(match ty {
73	        "function_call" => "function",
74	        "custom_tool_call" => "custom",
75	        "computer_call" => "computer",
76	        "local_shell_call" => "local_shell",
77	        "shell_call" => "shell",
78	        "apply_patch_call" => "apply_patch",
79	        "tool_search_call" => "tool_search",
80	        "mcp_approval_request" => "mcp_approval_request",
81	        _ => "item",
82	    })
83	}
84	
85	/// The fixed name of a built-in kind (spec § 5).
86	fn fixed_name(kind: &str) -> Option<&'static str> {
87	    match kind {
88	        "computer" => Some("computer"),
89	        "local_shell" => Some("local_shell"),
90	        "shell" => Some("shell"),
91	        "apply_patch" => Some("apply_patch"),
92	        "tool_search" => Some("tool_search"),
93	        _ => None,
94	    }
95	}
96	
97	/// An optional string field: absent or `null` is `None`, any other non-string is `Err`.
98	fn opt_text(v: Option<&Value>) -> Result<Option<String>, ()> {
99	    match v {
100	        None | Some(Value::Null) => Ok(None),
101	        Some(Value::String(s)) => Ok(Some(s.clone())),
102	        Some(_) => Err(()),
103	    }
104	}
105	
106	/// `model_dump(exclude_none=True)`: every object field whose value is `null` is dropped, at any
107	/// depth. A `null` element of an array stays.
108	fn strip_nulls(v: &mut Value) {
109	    match v {
110	        Value::Object(m) => {
111	            m.retain(|_, x| !x.is_null());
112	            m.values_mut().for_each(strip_nulls);
113	        }
114	        Value::Array(a) => a.iter_mut().for_each(strip_nulls),
115	        _ => {}
116	    }
117	}
118	
119	/// The compact JSON of an item without `status`, as the decided form of an item kind (spec § 5).
120	fn item_json(o: &Map<String, Value>, normalised: bool) -> String {
121	    let mut m = o.clone();
122	    m.remove("status");
123	    let mut v = Value::Object(m);
124	    if normalised {
125	        strip_nulls(&mut v);
126	    }
127	    v.to_string()
128	}
129	
130	/// The call a client runs for one output item (spec § 5, § 6.2), or `None` for an item that no
131	/// client runs and for a value that is no item. `normalised`: the SDK dropped the `null` fields.
132	///
133	/// A function or custom call whose name, body, call id or namespace has another JSON type than
134	/// the SDK reads becomes kind `item`, the whole item: no decided call of that kind can match it,
135	/// so a call the SDK cannot read as decided fails closed.
136	fn item_call(item: &Value, position: Option<u32>, normalised: bool) -> Option<ModelCall> {
137	    let Value::Object(o) = item else { return None };
138	    let ty = o.get("type").and_then(Value::as_str);
139	    let kind = match ty {
140	        Some(t) => kind_of_type(t)?,
141	        None => "item",
142	    };
143	    let call = |kind: &'static str, name: String, arguments: String, parsed: bool, id: Option<String>, namespace: Option<String>| ModelCall {
144	        choice: 0,
145	        kind,
146	        name,
147	        arguments,
148	        parsed,
149	        position,
150	        id,
151	        namespace,
152	    };
153	    let other = || {
154	        let id = match (opt_text(o.get("call_id")), opt_text(o.get("id"))) {
155	            (Ok(Some(c)), _) => Some(c),
156	            (_, Ok(i)) => i,
157	            _ => None,
158	        };
159	        call("item", ty.unwrap_or("").to_owned(), item_json(o, normalised), normalised, id, None)
160	    };
161	    let text = |k: &str| o.get(k).and_then(Value::as_str).map(str::to_owned);
162	    Some(match kind {
163	        "function" | "custom" => {
164	            let body = if kind == "function" { "arguments" } else { "input" };
165	            let (Some(name), Some(arguments), Some(id), Ok(namespace)) = (text("name"), text(body), text("call_id"), opt_text(o.get("namespace"))) else {
166	                return Some(other());
167	            };
168	            call(kind, name, arguments, false, Some(id), namespace)
169	        }
170	        "item" => other(),
171	        _ => {
172	            let name = match fixed_name(kind) {
173	                Some(n) => n.to_owned(),
174	                None => match text("name") {
175	                    Some(n) => n,
176	                    None => return Some(other()),
177	                },
178	            };
179	            let id = match kind {
180	                "mcp_approval_request" => text("id"),
181	                _ => match opt_text(o.get("call_id")) {
182	                    Ok(c) => c,
183	                    Err(()) => return Some(other()),
184	                },
185	            };
186	            let namespace = match kind {
187	                "mcp_approval_request" => match opt_text(o.get("server_label")) {
188	                    Ok(ns) => ns,
189	                    Err(()) => return Some(other()),
190	                },
191	                _ => None,
192	            };
193	            call(kind, name, item_json(o, normalised), normalised, id, namespace)
194	        }
195	    })
196	}
197	
198	/// The calls of an output list, each at its list position.
199	fn output_calls(output: &[Value], normalised: bool, calls: &mut Vec<ModelCall>) {
200	    for (i, item) in output.iter().enumerate() {
201	        calls.extend(item_call(item, Some(u32::try_from(i).expect("small")), normalised));
202	    }
203	}
204	
205	/// One call on several surfaces, shown the same way, is one call. Two different views stay two
206	/// calls.
207	fn dedupe(calls: Vec<ModelCall>) -> Vec<ModelCall> {
208	    let mut out: Vec<ModelCall> = Vec::new();
209	    for c in calls {
210	        if !out.contains(&c) {
211	            out.push(c);
212	        }
213	    }
214	    out
215	}
216	
217	/// An `output_index` as a position. A value that is no `u32` gets `u32::MAX`, which no decided
218	/// call has.
219	fn position_of(v: Option<&Value>) -> Option<u32> {
220	    Some(v.and_then(py_int).and_then(|i| u32::try_from(i).ok()).unwrap_or(u32::MAX))
221	}
222	
223	// ---- matching ----------------------------------------------------------------------------------
224	
225	/// A decided Responses call in the models' terms (spec § 5).
226	pub fn as_model_call(c: &ToolCall) -> ModelCall {
227	    ModelCall {
228	        choice: c.choice,
229	        kind: responses_kind_of(c.kind),
230	        name: c.name.clone(),
231	        arguments: c.arguments.clone(),
232	        parsed: false,
233	        position: Some(c.position),
234	        id: c.id.clone(),
235	        namespace: c.namespace.clone(),
236	    }
237	}
238	
239	/// Whether a model call matches a decided call (spec § 10.1, ruling F9): the same choice, kind,
240	/// name and call id; the same `output_index` where the SDK shows one; the same namespace; and the
241	/// same arguments. A function's raw `""`
242	/// matches the decided `{}` (749 § 11). A LangChain tool call (`parsed`) holds the parsed
243	/// arguments, and a custom call's `{"__arg1": input}`. An item kind matches as the JSON of the
244	/// item without `status`, after the SDK's `null` drop when `parsed`. The match is exact: a prefix
245	/// of allowed arguments is a failure (757 D2).
246	pub fn matches(mc: &ModelCall, d: &ModelCall) -> bool {
247	    if mc.choice != d.choice || mc.kind != d.kind || mc.name != d.name || mc.id != d.id {
248	        return false;
249	    }
250	    if mc.position.is_some() && mc.position != d.position {
251	        return false;
252	    }
253	    if mc.namespace != d.namespace {
254	        return false;
255	    }
256	    let parse = |s: &str| serde_json::from_str::<Value>(s).ok();
257	    match mc.kind {
258	        "function" if mc.parsed => {
259	            let full = if d.arguments.is_empty() { Some(json!({})) } else { parse(&d.arguments) };
260	            full.is_some() && parse(&mc.arguments) == full
261	        }
262	        "function" => mc.arguments == d.arguments || (mc.arguments.is_empty() && d.arguments == "{}"),
263	        "custom" if mc.parsed => parse(&mc.arguments) == Some(json!({"__arg1": d.arguments})),
264	        "custom" => mc.arguments == d.arguments,
265	        _ => {
266	            let (Some(mut got), Some(mut want)) = (parse(&mc.arguments), parse(&d.arguments)) else {
267	                return false;
268	            };
269	            if mc.parsed {
270	                strip_nulls(&mut got);
271	                strip_nulls(&mut want);
272	            }
273	            got == want
