#[test]
fn zz_stats() {
    use proptest::strategy::ValueTree;
    use proptest::test_runner::TestRunner;
    let mut r = TestRunner::deterministic();
    let st = responses_scenario();
    let (mut noq, mut clean, mut calls, mut blocked_streams, mut with_calls, mut aborted, mut trunc) = (0, 0, 0usize, 0, 0, 0, 0);
    let mut kinds = std::collections::BTreeMap::new();
    let n = 10_000;
    for _ in 0..n {
        let s = st.new_tree(&mut r).unwrap().current();
        for i in &s.items { *kinds.entry(format!("{:?}", i.kind)).or_insert(0) += 1; }
        if s.quirks.is_empty() { noq += 1; }
        let bytes = render_responses(&s);
        let o = drive(Format::OpenAiResponses, limits(OnFailure::Block), &cut(&bytes, &s.cuts), &block_named);
        if !o.core_failed() && !o.aborted { clean += 1; }
        if o.aborted { aborted += 1; }
        if o.metrics.contains(&Metric::OnFailure("truncated")) { trunc += 1; }
        calls += o.decided.len();
        if !o.decided.is_empty() { with_calls += 1; }
        if o.decided.iter().any(|(_, d)| !d.is_allow()) { blocked_streams += 1; }
    }
    eprintln!("STATS n={n} no_quirk={noq} clean={clean} aborted={aborted} truncated={trunc} decided_calls={calls} streams_with_decided={with_calls} streams_with_block={blocked_streams} kinds={kinds:?}");
}
EOF
