        if o.aborted { aborted += 1; }
        if o.metrics.contains(&Metric::OnFailure("truncated")) { trunc += 1; }
        calls += o.decided.len();
        if !o.decided.is_empty() { with_calls += 1; }
        if o.decided.iter().any(|(_, d)| !d.is_allow()) { blocked_streams += 1; }
